def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'
    if n >= 99:
        return 'D'

    opp_coops = sum(1 for h in history if h[1] == 'C')
    opp_coop_rate = opp_coops / n
    if opp_coop_rate < 0.25:
        return 'D'

    my_D = 0
    opp_D_after_my_D = 0
    my_C = 0
    opp_D_after_my_C = 0
    for i in range(n - 1):
        me, opp = history[i]
        next_opp = history[i + 1][1]
        if me == 'D':
            my_D += 1
            if next_opp == 'D':
                opp_D_after_my_D += 1
        else:
            my_C += 1
            if next_opp == 'D':
                opp_D_after_my_C += 1

    if my_D >= 1 and opp_D_after_my_D == 0 and opp_coop_rate > 0.7:
        return 'D'

    if my_D >= 2 and my_C >= 2:
        p_D = opp_D_after_my_D / my_D
        p_C = opp_D_after_my_C / my_C
        if p_D - p_C > 0.25:
            return 'C'
        elif p_C - p_D > 0.25:
            return 'D'
        else:
            return 'D'

    return 'C'
